mapper.select:
SELECT HOMELESS_HEAD_YN
  FROM MEMBER
 WHERE MEMBER_ID = #{memberId}

SELECT BIRTH_DATE, MILITARY_MONTHS, HIRE_DATE, COMPANY_SIZE, HOMELESS_HEAD_YN
  FROM MEMBER
 WHERE MEMBER_ID = #{memberId}

SELECT TYPE_ID
  FROM DEDUCTION_TYPE
 WHERE TAX_YEAR = #{taxYear}
   AND TYPE_CODE = #{typeCode}
   AND (SALARY_MIN = 0 OR #{totalSalary} > SALARY_MIN)
   AND (SALARY_MAX IS NULL OR #{totalSalary} <= SALARY_MAX)
